-- Детский мир — руками, и вот почему.
--
-- Автоматический отбор его отбрасывает: пути `/dm/` и `/logistics/` слова о
-- вакансиях не содержат. Но у него весь сайт jobs.detmir.ru — карьерный, и
-- двенадцать ссылок на нём это «кладовщик», «комплектовщик товара»,
-- «упаковщик», «водитель погрузчика», «оператор», «продавец-кассир» — ровно
-- та аудитория, ради которой JobToo и существует. Проверено глазами по
-- разметке страницы.
--
-- Разделов два и нужны оба: в `/dm/` магазины, в `/logistics/` склады.
--
-- Ссылки на странице проставлены через http, при том что по https те же
-- страницы открываются (проверено: /logistics/komplektovshchik-tovara отдаёт
-- 200 и содержит название должности). Схему поднимает cf_json_url — только
-- для своего же хоста.

update public.jm_ext_sources s
   set connector_config = jsonb_set(
         s.connector_config,
         '{endpoints}',
         (s.connector_config->'endpoints') || (
           select coalesce(jsonb_agg(c.value order by c.ord), '[]'::jsonb)
             from jsonb_array_elements(jsonb_build_array(
               jsonb_build_object(
                 'url', 'https://jobs.detmir.ru',
                 'mode', 'html_links',
                 'map', jsonb_build_object(
                   'link_path', '/logistics/',
                   'company_const', 'Детский мир'
                 )
               ),
               jsonb_build_object(
                 'url', 'https://jobs.detmir.ru/',
                 'mode', 'html_links',
                 'map', jsonb_build_object(
                   'link_path', '/dm/',
                   'company_const', 'Детский мир'
                 )
               )
             )) with ordinality as c(value, ord)
            where not exists (
              select 1
                from jsonb_array_elements(s.connector_config->'endpoints') e
               where e->>'url' = c.value->>'url'
                 and e->'map'->>'link_path' = c.value->'map'->>'link_path'
            )
         ))
 where s.id = 'career'
   and jsonb_typeof(s.connector_config->'endpoints') = 'array';

commit;

notify pgrst, 'reload schema';

